INSERT INTO public.map_pin (map_id, name, description, longitude, latitude)
SELECT m.id, #{name}, #{description,jdbcType=VARCHAR}, #{longitude}, #{latitude}
FROM public.travel_map m
WHERE m.id = #{mapId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
  AND EXISTS (
      SELECT 1 FROM public.user_account a
      WHERE a.id = #{actorId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
        AND a.status = 1
        AND (m.owner_id = a.id OR (a.role = 'admin' AND m.visibility = 'public'))
  )
RETURNING

UPDATE public.map_pin p
SET name = #{name},
    description = #{description,jdbcType=VARCHAR},
    longitude = #{longitude},
    latitude = #{latitude}
WHERE p.id = #{pinId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
  AND p.map_id = #{mapId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
  AND EXISTS (
      SELECT 1 FROM public.travel_map m
      JOIN public.user_account a
        ON a.id = #{actorId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
      WHERE m.id = p.map_id
        AND a.status = 1
        AND (m.owner_id = a.id OR (a.role = 'admin' AND m.visibility = 'public'))
  )
RETURNING

DELETE FROM public.map_pin p
WHERE p.id = #{pinId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
  AND p.map_id = #{mapId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
  AND EXISTS (
      SELECT 1 FROM public.travel_map m
      JOIN public.user_account a
        ON a.id = #{actorId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
      WHERE m.id = p.map_id
        AND a.status = 1
        AND (m.owner_id = a.id OR (a.role = 'admin' AND m.visibility = 'public'))
  )
RETURNING p.id

UPDATE public.travel_map m
SET updated_at = clock_timestamp()
WHERE m.id = #{mapId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
  AND EXISTS (
      SELECT 1 FROM public.map_pin p
      WHERE p.id = #{pinId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
        AND p.map_id = m.id
        AND (p.name IS DISTINCT FROM #{name}
             OR p.description IS DISTINCT FROM #{description,jdbcType=VARCHAR}
             OR p.longitude IS DISTINCT FROM #{longitude}
             OR p.latitude IS DISTINCT FROM #{latitude})
  )
  AND EXISTS (
      SELECT 1 FROM public.user_account a
      WHERE a.id = #{actorId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
        AND a.status = 1
        AND (m.owner_id = a.id OR (a.role = 'admin' AND m.visibility = 'public'))
  )
RETURNING 1

UPDATE public.travel_map m
SET updated_at = clock_timestamp()
WHERE m.id = #{mapId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
  AND EXISTS (
      SELECT 1 FROM public.user_account a
      WHERE a.id = #{actorId,typeHandler=com.guidepins.config.PostgresUuidTypeHandler}
        AND a.status = 1
        AND (m.owner_id = a.id OR (a.role = 'admin' AND m.visibility = 'public'))
  )
RETURNING 1
